	// The name of the struct to convert
	structName := "Person"

	// Generate the Avro schema based on the given struct
	generateAvroSchema(goFile, structName)
}

// Function to generate Avro schema from the given Go struct
func generateAvroSchema(goFilePath string, structName string) error {
	file, err := ioutil.ReadFile(goFilePath)
	if err != nil {
		return fmt.Errorf("failed to read file: %w", err)
	}

	var golangStruct *proto.Message
	err = proto.Unmarshal(file, &golangStruct)
	if err != nil {
		return fmt.Errorf("error unmarshalling file content: %w", err)
	}

	// Extract the field names from the struct fields
	fieldNames := make([]string, len(golangStruct.Fields))
	for i, f := range golangStruct.Fields {
		fieldNames[i] = f.Name
	}

	// Create Avro schemas for each field with their corresponding types
	schemas := []struct {
		Name   string
		Type   string
		Fields []string
	}{
		{"name", "STRING"},
		{"age", "INT32"},
	}

	for _, fieldName := range fieldNames {
		for _, schema := range schemas {
			if fieldName == schema.Name {
				break
			}
		}
	}

	// Serialize the Avro schema as JSON
	jsonString, err := json.MarshalIndent(schemas, "", "\t")
	if err != nil {
		return fmt.Errorf("error marshalling schema: %w", err)
	}

	// Write the Avro schema to a file
	outPath := fmt.Sprintf("%s.avsc", structName)
	err = ioutil.WriteFile(outPath, jsonString, 0644)
	if err != nil {
		return fmt.Errorf("error writing Avro schema file: %w", err)
	}

	fmt.Printf("Generated Avro schema at: %s\n", outPath)
	return nil
}
